                        p3 = _mm512_fmadd_pd(_mm512_set1_pd(e[12]), r0_2, p3);
                        q0 = _mm512_fmadd_pd(_mm512_set1_pd(e[1]), r0_11, q0);
                        q1 = _mm512_fmadd_pd(_mm512_set1_pd(e[5]), r0_11, q1);
                        q2 = _mm512_fmadd_pd(_mm512_set1_pd(e[9]), r0_11, q2);
                        q3 = _mm512_fmadd_pd(_mm512_set1_pd(e[13]), r0_11, q3);
