                        p3 = _mm512_fmadd_pd(_mm512_set1_pd(e[14]), r0_16, p3);
                        q0 = _mm512_fmadd_pd(_mm512_set1_pd(e[3]), r0_18, q0);
                        q1 = _mm512_fmadd_pd(_mm512_set1_pd(e[7]), r0_18, q1);
                        q2 = _mm512_fmadd_pd(_mm512_set1_pd(e[11]), r0_18, q2);
