                        double *a2 = ag + (size_t)pr[2] * n;
                        __m512d p2 = _mm512_maskz_loadu_pd(mk, a2), q2 = _mm512_setzero_pd();
                        double *a3 = ag + (size_t)pr[3] * n;
                        __m512d p3 = _mm512_maskz_loadu_pd(mk, a3), q3 = _mm512_setzero_pd();
                        p0 = _mm512_fmadd_pd(_mm512_set1_pd(e[0]), r0_8, p0);
                        p1 = _mm512_fmadd_pd(_mm512_set1_pd(e[1]), r0_8, p1);
                        p2 = _mm512_fmadd_pd(_mm512_set1_pd(e[2]), r0_8, p2);
                        p3 = _mm512_fmadd_pd(_mm512_set1_pd(e[3]), r0_8, p3);
